script.exec:
pm.test("201 pada run yang tuntas (409 bila run sebelumnya terputus)", function () {
    pm.expect([201, 409]).to.include(pm.response.code);
});
pm.test("sesi aktif dan platnya sesuai", function () {
    if (pm.response.code === 201) {
        pm.expect(pm.response.json().status).to.eql("active");
        pm.expect(pm.response.json().plate_in).to.eql(pm.collectionVariables.get("plate_probe"));
    }
});

pm.test("409 duplicate_active_session", function () {
    pm.response.to.have.status(409);
    pm.expect(pm.response.json().code).to.eql("duplicate_active_session");
});
pm.test("yang bentrok adalah nim", function () {
    pm.expect(pm.response.json().details.field).to.eql("nim");
});

pm.test("409 duplicate_active_session", function () {
    pm.response.to.have.status(409);
    pm.expect(pm.response.json().code).to.eql("duplicate_active_session");
});
pm.test("yang bentrok adalah plate", function () {
    pm.expect(pm.response.json().details.field).to.eql("plate");
});

const milikRun = [
    pm.collectionVariables.get("session_id"),
    pm.collectionVariables.get("session_id_2"),
    pm.collectionVariables.get("session_id_3"),
    pm.collectionVariables.get("session_id_probe")
].map(String);

pm.test("200 dan berbentuk daftar", function () {
    pm.response.to.have.status(200);
    pm.expect(pm.response.json()).to.be.an("array");
});
pm.test("tidak ada sesi run ini yang masih aktif", function () {
    const tertinggal = pm.response.json().filter(function (r) {
        return milikRun.indexOf(String(r.id)) !== -1;
    });
    pm.expect(tertinggal).to.be.empty;
});
